begin read only; set local statement_timeout='25s';
select jsonb_build_object(
 'checked_at_utc',now(),
 'orders_production',(select count(*) from public.orders where payment_environment='production' and psp='solidgate'),
 'renewals_production',(select count(*) from public.renewal_events where payment_environment='production' and solidgate_invoice_id is not null),
 'duplicate_order_keys',(select count(*) from(select payment_environment,solidgate_order_id from public.orders where solidgate_order_id is not null group by 1,2 having count(*)>1)t),
 'duplicate_invoice_keys',(select count(*) from(select payment_environment,solidgate_invoice_id from public.renewal_events where solidgate_invoice_id is not null group by 1,2 having count(*)>1)t),
 'duplicate_entitlement_keys',(select count(*) from(select payment_environment,user_id,product_slug from public.entitlements group by 1,2,3 having count(*)>1)t),
 'duplicate_subscription_bindings',(select count(*) from(select payment_environment,solidgate_subscription_id from public.orders where psp='solidgate' and solidgate_subscription_id is not null group by 1,2 having count(*)>1)t),
 'duplicate_live_customer_product_subscriptions',(select count(*) from(select solidgate_customer_email,product_slug from public.orders where payment_environment='production' and psp='solidgate' and solidgate_subscription_id is not null and status in ('active','trialing','past_due') group by 1,2 having count(distinct solidgate_subscription_id)>1)t),
 'initial_invoice_in_renewals',(select count(*) from public.renewal_events where payment_environment='production' and solidgate_invoice_id is not null and subscription_term_number=0),
 'known_paid_invoice_raw_missing_ledger',(select count(distinct (w.environment,inv.key)) from public.solidgate_webhook_events w cross join lateral jsonb_each(coalesce(w.payload->'invoices','{}'::jsonb)) inv where w.environment='production' and w.type='subscription.updated.v2' and inv.value->>'status'='success' and (inv.value->>'subscription_term_number')~'^[1-9][0-9]*$' and exists(select 1 from public.orders o where o.payment_environment=w.environment and o.solidgate_subscription_id=w.payload#>>'{subscription,id}') and not exists(select 1 from public.renewal_events r where r.payment_environment=w.environment and r.solidgate_invoice_id=coalesce(inv.value->>'id',inv.key))),
 'renewal_balance_mismatch_current_reducer',(select count(*) from public.renewal_events where payment_environment='production' and solidgate_invoice_id is not null and gross_amount_cents is not null and amount_cents<>greatest(0,gross_amount_cents-greatest(refunded_amount_cents,case when chargeback_status in ('reversed','resolved_reversal') then 0 else chargeback_amount_cents end))),
 'order_balance_mismatch_settled_refunded',(select count(*) from public.orders where payment_environment='production' and psp='solidgate' and solidgate_payment_status in ('settle_ok','refunded') and solidgate_original_amount_cents is not null and amount_cents<>greatest(0,solidgate_original_amount_cents-greatest(solidgate_refunded_amount_cents,case when solidgate_chargeback_status in ('reversed','resolved_reversal') then 0 else solidgate_chargeback_amount_cents end))),
 'pending_with_capture_status',(select count(*) from public.orders where payment_environment='production' and psp='solidgate' and status='pending' and solidgate_payment_status in ('settle_ok','partial_settled')),
 'failed_subscription_events',(select count(*) from public.solidgate_webhook_events where environment='production' and type='subscription.updated.v2' and status='failed'),
 'non_uuid_failed_events',(select count(*) from public.solidgate_webhook_events where environment='production' and type='subscription.updated.v2' and status='failed' and last_error like '%invalid input syntax for type uuid%'),
 'non_uuid_failed_subscriptions',(select count(distinct payload#>>'{subscription,id}') from public.solidgate_webhook_events where environment='production' and type='subscription.updated.v2' and status='failed' and last_error like '%invalid input syntax for type uuid%'),
 'non_uuid_failed_renew_events',(select count(*) from public.solidgate_webhook_events where environment='production' and type='subscription.updated.v2' and status='failed' and last_error like '%invalid input syntax for type uuid%' and payload->>'callback_type'='renew'),
 'non_uuid_failed_bound_subscriptions',(select count(*) from public.solidgate_webhook_events w where environment='production' and type='subscription.updated.v2' and status='failed' and last_error like '%invalid input syntax for type uuid%' and exists(select 1 from public.orders o where o.payment_environment=w.environment and o.solidgate_subscription_id=w.payload#>>'{subscription,id}')),
 'uncompleted_fulfillment',(select count(*) from public.solidgate_fulfillment_outbox where environment='production' and status<>'completed'),
 'uncompleted_analytics',(select count(*) from public.solidgate_analytics_outbox where environment='production' and status<>'completed'),
 'duplicate_intro_refund_queue',(select count(*) from public.solidgate_intro_claims_needing_refund where payment_environment='production')
) audit; commit;
